DO $deploy$ DECLARE h text;p jsonb;BEGIN
SELECT html INTO h FROM public.frontend_snapshots WHERE key='stable-v10-clean' FOR UPDATE;
IF md5(h)<>'7060e5acc2a672a4a061bbe3aac8a158' THEN RAISE EXCEPTION 'Live baseline changed';END IF;
INSERT INTO public.frontend_snapshots(key,html) VALUES('backup-admin-before-form-recovery-v273-20261016',h) ON CONFLICT(key) DO NOTHING;
IF (SELECT md5(html) FROM public.frontend_snapshots WHERE key='backup-admin-before-form-recovery-v273-20261016')<>'7060e5acc2a672a4a061bbe3aac8a158' THEN RAISE EXCEPTION 'Backup differs';END IF;
FOR p IN SELECT value FROM jsonb_array_elements($patches$[{"old":"/* v63: messages/dashboard update via initial load + Realtime + resume sync; no periodic polling */","new":"(function(){\n'use strict';\nlet rows=[],loading=null,loadError=\"\";const $=id=>document.getElementById(id);\nconst labels={dog_name:'Meno psíka',dog_breed:'Plemeno',dog_weight_kg:'Váha',dog_sex:'Pohlavie',dog_age_text:'Vek',dog_neutered:'Kastrácia',interest_reason:'Využívanie škôlky',dog_allergies:'Alergie a zdravotné obmedzenia',dog_temperament:'Povaha a ďalšie informácie',dog_info:'Ďalšie informácie'};\nfunction fields(p){return Object.entries(labels).filter(([k])=>p?.[k]!==undefined&&p[k]!==null&&p[k]!=='').map(([k,label])=>'<div class=\"history-row\"><strong>'+esc(label)+'</strong><div style=\"white-space:pre-wrap;overflow-wrap:anywhere\">'+esc(typeof p[k]==='boolean'?(p[k]?'Áno':'Nie'):p[k])+'</div></div>').join('')}\nfunction contents(){\n const q=String($('dogSearch')?.value||'').trim().toLowerCase(),visible=rows.filter(r=>!q||[r.owner_name,r.phone,r.email,r.dog_names].some(v=>String(v||'').toLowerCase().includes(q)));\n return '<details class=\"card\" '+(rows.length?'open':'')+'>'+'<summary style=\"cursor:pointer;min-height:44px\"><strong>⚠ Neúspešné odoslania</strong> <span class=\"pill warn\">'+visible.length+'</span></summary><button type=\"button\" class=\"btn secondary compact\" data-recovery-refresh>Obnoviť</button>'+(loadError?'<p class=\"warning-box\">'+esc(loadError)+'</p>':'')+(!visible.length&&!loadError?'<p class=\"muted small\">Zatiaľ bez neúspešných odoslaní.</p>':'')+visible.map(r=>'<article class=\"note\" style=\"margin-top:10px\"><strong>'+esc(r.owner_name)+'</strong><div class=\"muted small\">'+(r.form_type==='lead'?'Záujem':'Prihláška')+' · '+esc(webSubmissionDate(r.created_at))+'</div><a class=\"phone\" href=\"tel:'+esc(r.phone)+'\">'+esc(r.phone)+'</a>'+(r.email?'<div>'+esc(r.email)+'</div>':'')+(r.dog_names?'<div>'+esc(r.dog_names)+'</div>':'')+(r.interest_reason?'<div>'+esc(r.interest_reason)+'</div>':'')+'<details><summary>Údaje z formulára</summary>'+fields(r.recovery_payload)+(r.recovery_payload?.dogs||[]).map((d,i)=>'<h4>'+(i+1)+'. psík</h4>'+fields(d)).join('')+'</details><button type=\"button\" class=\"btn secondary compact\" data-recovery-handled=\"'+esc(r.attempt_id)+'\">Označiť ako vybavené</button></article>').join('')+'</details>';\n}\nfunction html(){return '<section data-recovery-modal>'+contents()+'</section>'}\nfunction render(){\n let root=$('formRecoveryV273');if(!root){const anchor=$('webApplicationsList')?.closest('.card');if(!anchor)return;root=document.createElement('section');root.id='formRecoveryV273';root.dataset.recoveryModal='';anchor.before(root)}\n document.querySelectorAll('[data-recovery-modal]').forEach(host=>host.innerHTML=contents());\n}\nasync function load(){if(loading)return loading;loading=(async()=>{try{const r=await withJwtRetry(()=>supabase.from('web_form_recoveries_v273').select('attempt_id,created_at,form_type,owner_name,phone,email,dog_names,interest_reason,recovery_payload,error_stage').is('resolved_submission_id',null).is('handled_at',null).order('created_at',{ascending:false}).limit(100));if(r.error)throw r.error;loadError='';rows=(r.data||[]).filter(r=>r.error_stage!=='received'||Date.now()-Date.parse(r.created_at)>60000);render()}catch(e){loadError='Zachránené formuláre sa nepodarilo načítať. Skúste obnoviť prehľad.';render()}})();try{return await loading}finally{loading=null}}\nconst originalLoad=loadData;loadData=async function(...args){await originalLoad(...args);await load()};window.loadData=loadData;\nconst originalRender=renderWebSubmissions;renderWebSubmissions=function(...args){const value=originalRender(...args);render();return value};\nwindow.addEventListener('focus',()=>{if(!$('mainView')?.classList.contains('hidden'))void load()});\ndocument.addEventListener('click',event=>{const b=event.target.closest('[data-recovery-refresh],[data-recovery-handled]');if(!b)return;event.preventDefault();if(b.hasAttribute('data-recovery-refresh')){void load();return}b.disabled=true;void(async()=>{try{const r=await withJwtRetry(()=>supabase.from('web_form_recoveries_v273').update({handled_at:new Date().toISOString()}).eq('attempt_id',b.dataset.recoveryHandled));if(r.error)throw r.error;await load()}catch(e){alert(e.message||'Zmenu sa nepodarilo uložiť.');b.disabled=false}})()});\nwindow.formRecoveryV273={load,render,html};\n})();\n\n/* v63: messages/dashboard update via initial load + Realtime + resume sync; no periodic polling */"},{"old":"else if(kind==='interest')markup=dashInterestHtmlV42();","new":"else if(kind==='interest'){void window.formRecoveryV273?.load();markup=dashInterestHtmlV42()+(window.formRecoveryV273?.html()||'');}"}]$patches$::jsonb) LOOP
IF (length(h)-length(replace(h,p->>'old','')))/length(p->>'old')<>1 THEN RAISE EXCEPTION 'Patch anchor differs';END IF;
h:=replace(h,p->>'old',p->>'new');END LOOP;
IF md5(h)<>'66f5ff1b4ae2ac53c850200376f85a23' THEN RAISE EXCEPTION 'Result differs';END IF;
UPDATE public.frontend_snapshots SET html=h WHERE key='stable-v10-clean';END $deploy$;
